package common

import chisel3._
import chisel3.util._

/** FMA command: computes ina * inb + inc */
class FmaCmd extends Bundle {
  val ina = new Fp32
  val inb = new Fp32
  val inc = new Fp32
}

/** Intermediate state after Stage 1 (multiply). */
class FmaState1 extends Bundle {
  // Product sign
  val prodSign    = Bool()
  // Product biased exponent (before normalization, can overflow into extra bit)
  val prodExp     = UInt(9.W)   // 9 bits to detect overflow
  // Product mantissa (full 48-bit product of two 24-bit significands)
  val prodMantissa = UInt(48.W)
  // Whether this is a special case: NaN or Inf
  val isNaN       = Bool()
  val isInf       = Bool()
  // Addend (inc)
  val addSign     = Bool()
  val addExp      = UInt(8.W)
  val addMantissa = UInt(23.W)
}

/** Intermediate state after Stage 2 (align addend). */
class FmaState2 extends Bundle {
  // Sign and exponent of the result (from product)
  val resultSign   = Bool()
  val resultExp    = UInt(9.W)
  // Product mantissa (48 bits, with implicit 1 at bit 47)
  val prodMantissa = UInt(48.W)
  // Aligned addend mantissa (48 bits, shifted to match product's exponent)
  val addAligned   = UInt(48.W)
  val addSign      = Bool()
  // Special case flags
  val isNaN        = Bool()
  val isInf        = Bool()
}

object Fma {
  /** Stage 1: Multiply ina * inb, record inc for later addition. */
  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val s1 = Wire(new FmaState1)

    val a = cmd.ina
    val b = cmd.inb
    val c = cmd.inc

    // Product sign
    s1.prodSign := a.sign ^ b.sign

    // Significands with implicit leading 1
    val sigA = Cat(1.U(1.W), a.mantissa)  // 24 bits
    val sigB = Cat(1.U(1.W), b.mantissa)  // 24 bits

    // Full 48-bit product
    s1.prodMantissa := sigA * sigB

    // Product exponent: sum of biased exponents minus bias (127)
    // biased_exp_a + biased_exp_b - 127
    val expSum = a.exponent +& b.exponent  // up to 9 bits
    // subtract bias: expSum - 127 + 127 (re-bias) = expSum - 127
    // But we keep as biased: expProd = expA + expB - 127
    s1.prodExp := expSum - 127.U

    // Special cases
    val aIsZero  = a.isZero()
    val bIsZero  = b.isZero()
    val aIsInf   = a.isInf()
    val bIsInf   = b.isInf()
    val aIsNan   = a.isNan()
    val bIsNan   = b.isNan()
    val cIsNan   = c.isNan()

    // NaN if any input is NaN, or 0*Inf
    s1.isNaN := aIsNan || bIsNan || cIsNan || (aIsZero && bIsInf) || (bIsZero && aIsInf)
    s1.isInf := !s1.isNaN && (aIsInf || bIsInf)

    // Zero * something = 0 (for product), handle by setting prodExp to 0
    when(aIsZero || bIsZero) {
      s1.prodMantissa := 0.U
      s1.prodExp      := 0.U
    }

    // Addend
    s1.addSign     := c.sign
    s1.addExp      := c.exponent
    s1.addMantissa := c.mantissa

    s1
  }

  /** Stage 2: Align addend mantissa to product's exponent. */
  def FmaStage2(s1: FmaState1): FmaState2 = {
    val s2 = Wire(new FmaState2)

    s2.isNaN     := s1.isNaN
    s2.isInf     := s1.isInf
    s2.resultSign := s1.prodSign
    s2.resultExp  := s1.prodExp

    // Product significand is s1.prodMantissa (48-bit)
    // The implicit radix point is at bit 47-46 (leading 1 can be at bit 47)
    // Actual position: the product of two 1.xxx * 1.xxx is in range [1.0, 4.0)
    // The leading bit is at position 47 or 46.
    s2.prodMantissa := s1.prodMantissa

    // Addend significand: 1.mantissa (24 bits)
    val addSig = Cat(1.U(1.W), s1.addMantissa)  // 24 bits

    // The product has its "integer" bit at position 47 (worst case)
    // representing value: prodMantissa * 2^(prodExp - 46)
    // The addend represents: addSig * 2^(addExp - 127 - 22)
    //                      = addSig * 2^(addExp - 149)
    // We need to align addend to match product's exponent.
    // Product integer exponent = prodExp - 46
    // Addend integer exponent  = addExp - 149 = addExp - 127 - 22

    // Shift addend to align with product:
    // Difference in exponent: (prodExp - 46) - (addExp - 149)
    //                       = prodExp - 46 - addExp + 149
    //                       = prodExp - addExp + 103
    // If positive: shift addend right by that amount
    // If negative: shift addend left (product is smaller, or addend is bigger)
    // We'll work in fixed-point aligned at the product's scale.

    // Extend addend to 48 bits, positioned at bit 23 (lsb of 24-bit sig at bit 0)
    val addSig48 = Cat(0.U(24.W), addSig)  // 48 bits, sig in [23:0]

    // We want both to be at the same binary point.
    // Product's LSB is at exponent = prodExp - 46 (since bit 0 of the 48-bit product
    // corresponds to 2^(prodExp-46)).
    // Addend's LSB is at exponent = addExp - 127 - 22 = addExp - 149.
    // Shift to align: need to move addend so its LSB aligns with product LSB.
    // Delta = (addExp - 149) - (prodExp - 46) = addExp - prodExp - 103
    // If delta > 0: addend has larger exponent -> shift addend left by delta
    // If delta < 0: addend has smaller exponent -> shift addend right by |delta|

    // Use signed arithmetic via SInt-like approach
    val prodExpSigned = s1.prodExp.asSInt  // 9-bit signed
    val addExpSigned  = s1.addExp.asSInt   // 8-bit signed

    // delta = addExp - prodExp - 103
    val delta = addExpSigned - prodExpSigned - 103.S

    val addAligned = Wire(UInt(48.W))
    when(s1.addExp === 0.U && s1.addMantissa === 0.U) {
      // addend is zero
      addAligned := 0.U
    }.elsewhen(delta >= 0.S) {
      // Shift left - but clamp to avoid huge shifts
      val shiftAmt = Mux(delta > 47.S, 47.U, delta.asUInt(6, 0))
      addAligned := (addSig48 << shiftAmt)(47, 0)
    }.otherwise {
      // Shift right
      val shiftAmt = Mux(-delta > 47.S, 48.U, (-delta).asUInt(6, 0))
      addAligned := (addSig48 >> shiftAmt)(47, 0)
    }

    s2.addAligned := addAligned
    s2.addSign    := s1.addSign

    s2
  }

  /** Stage 3: Add product and addend, normalize, produce Fp32 result. */
  def FmaStage3(s2: FmaState2): Fp32 = {
    val result = Wire(new Fp32)

    // Handle special cases first
    when(s2.isNaN) {
      // Canonical quiet NaN
      result.sign     := false.B
      result.exponent := 0xFF.U
      result.mantissa := (1 << 22).U  // quiet NaN
    }.elsewhen(s2.isInf) {
      result.sign     := s2.resultSign
      result.exponent := 0xFF.U
      result.mantissa := 0.U
    }.otherwise {
      // Both product and addend are finite.
      // Perform the addition in 49-bit two's complement.
      // prodMantissa is the raw 48-bit product; the leading 1 is at bit 47 or 46.
      // We extend to 49 bits with a sign bit.

      val prodVal = Cat(0.U(1.W), s2.prodMantissa)   // 49-bit unsigned
      val addVal  = Cat(0.U(1.W), s2.addAligned)     // 49-bit unsigned

      // Convert both to signed (two's complement) based on their signs
      // Positive sign -> value as-is; Negative sign -> negate
      val prodSigned = Mux(s2.resultSign, (~prodVal) + 1.U, prodVal)
      val addSigned  = Mux(s2.addSign,    (~addVal)  + 1.U, addVal)

      // Sum in 50-bit (to catch carry)
      val sumRaw = Cat(0.U(1.W), prodSigned) + Cat(0.U(1.W), addSigned)  // 50-bit

      // Determine result sign: MSB of 49-bit signed result indicates negative
      val sumSign = sumRaw(49)
      val sumMag  = Mux(sumSign, (~sumRaw(48, 0)) + 1.U, sumRaw(48, 0))  // 49-bit magnitude

      // Find leading 1 in sumMag
      // sumMag can be up to 49 bits; use PriorityEncoder on reversed
      val leadPos = PriorityEncoder(Reverse(sumMag))  // position of highest set bit (0-based)

      // Normalize: the leading 1 should end up at the implied position.
      // The product exponent tells us where bit 47 of s2.prodMantissa corresponds.
      // prodMantissa bit 47 corresponds to 2^(prodExp - 46) ... but we need to be careful.
      // Actually after alignment, the "integer bit" (leading 1) of the product was at
      // position 47 in the 48-bit product. After extending to 49-bit, the product's
      // leading 1 is at position 47 (bit 47 of prodVal = bit 47 of prodMantissa).
      //
      // The exponent of the result: if leading 1 is at bit `leadPos` of sumMag,
      // then the actual exponent = prodExp - 46 + leadPos - 1 + 127
      // Wait, let me re-derive:
      // prodMantissa represents value: prod_significand * 2^(prodExp - 46)
      // where prod_significand is a 48-bit integer in range [2^46, 2^48).
      // The leading 1 of prod is at bit 47 (or 46 for unormalized).
      //
      // After summing, sumMag has leading 1 at bit `leadPos`.
      // The actual value = sumMag * 2^(prodExp - 46)
      // = (sumMag >> leadPos) * 2^(prodExp - 46 + leadPos)
      // In FP32: result = 1.mantissa * 2^(biased_exp - 127)
      // So biased_exp - 127 = prodExp - 46 + leadPos - 1  (subtract 1 because leading 1 is implicit)
      // biased_exp = prodExp + leadPos - 47 + 127
      //            = prodExp + leadPos + 80

      // Wait - actually prodExp is already biased (prodExp = expA + expB - 127).
      // The product value = prodMantissa * 2^(prodExp - 46)
      // Note: prodMantissa's leading 1 is at bit 47 for normalized inputs, so
      // prodMantissa / 2^47 is in [1,2), and value = (prodMantissa/2^47) * 2^(prodExp - 46 + 47)
      //                                             = (prodMantissa/2^47) * 2^(prodExp + 1)
      // But that's the product of two numbers each with leading 1, so the product is in [1,4).
      // The leading 1 is at bit 47 or 46.
      //
      // Re-derive cleanly:
      // sumMag is a non-negative integer.
      // sumMag * 2^(prodExp - 46) = result value (in terms of the original representation)
      // Leading bit of sumMag is at position leadPos (0-indexed from LSB).
      // So sumMag = (1 + frac) * 2^leadPos  where frac has 23 bits for FP32.
      // result value = (1 + frac) * 2^leadPos * 2^(prodExp - 46)
      //              = (1 + frac) * 2^(prodExp - 46 + leadPos)
      // FP32 biased exponent: e_biased = (prodExp - 46 + leadPos) + 127
      //                               = prodExp + leadPos + 81

      val rawExp = s2.resultExp.asSInt + leadPos.asSInt + 81.S  // signed to detect underflow

      // Extract mantissa: leadPos bits from sumMag starting at bit (leadPos-1) down to (leadPos-23)
      // i.e., bits [leadPos-1 : leadPos-23] of sumMag
      val shiftedMantissa = sumMag >> (leadPos - 23.U)  // shift so bit 23 is the leading 1, bits [22:0] are mantissa

      // Round-to-nearest-even
      val roundBit  = Mux(leadPos >= 23.U, sumMag((leadPos - 23.U).asUInt), 0.U)(0)
      val stickyMask = Mux(leadPos >= 24.U, ((1.U << (leadPos - 24.U)) - 1.U)(48, 0), 0.U(49.W))
      val stickyBit = (sumMag & stickyMask).orR
      val doRound   = roundBit && (stickyBit || shiftedMantissa(0))
      val mantissaRaw = shiftedMantissa(22, 0)
      val mantissaRounded = Mux(doRound, mantissaRaw +& 1.U, mantissaRaw.asUInt)
      val mantissaOverflow = doRound && mantissaRounded(23)
      val finalMantissa = Mux(mantissaOverflow, 0.U(23.W), mantissaRounded(22, 0))
      val finalExpAdj   = Mux(mantissaOverflow, rawExp + 1.S, rawExp)

      val isZeroResult = (sumMag === 0.U)

      when(isZeroResult) {
        result.sign     := false.B
        result.exponent := 0.U
        result.mantissa := 0.U
      }.elsewhen(finalExpAdj >= 255.S) {
        // Overflow -> Infinity
        result.sign     := sumSign
        result.exponent := 0xFF.U
        result.mantissa := 0.U
      }.elsewhen(finalExpAdj <= 0.S) {
        // Underflow -> Zero (flush to zero; subnormals not supported)
        result.sign     := sumSign
        result.exponent := 0.U
        result.mantissa := 0.U
      }.otherwise {
        result.sign     := sumSign
        result.exponent := finalExpAdj(7, 0).asUInt
        result.mantissa := finalMantissa
      }
    }

    result
  }
}

