import chisel3._
import chisel3.util._

/** Round-robin arbiter with N inputs and 1 output.
  *
  * Uses ArbiterIO which provides:
  *   io.in:     Vec(n, Flipped(Decoupled(gen)))
  *   io.out:    Decoupled(gen)
  *   io.chosen: UInt(log2Ceil(n).W)
  *
  * Behavior:
  *   - Selects among valid inputs in round-robin order.
  *   - lastGrant register tracks which input was last granted.
  *   - When multiple inputs are valid, picks the next one after lastGrant.
  *   - io.out.valid   = any input is valid
  *   - io.out.bits    = bits of chosen input
  *   - io.chosen      = index of chosen input
  *   - io.in(chosen).ready = io.out.ready (others = 0)
  *   - On clock edge when io.out.valid && io.out.ready: update lastGrant
  */
class CoralNPURRArbiter[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new ArbiterIO(gen, n))

  // lastGrant: the index of the last granted input (starts at n-1 so 0 is first)
  val lastGrant = RegInit((n - 1).U(log2Ceil(n).W))

  // Find the chosen input: scan starting from lastGrant+1
  // chosen = first valid input in round-robin order after lastGrant
  val chosen = Wire(UInt(log2Ceil(n).W))
  chosen := lastGrant  // default (shouldn't matter if none valid)

  // Build priority: inputs after lastGrant first, then wrap around
  val anyValid = io.in.map(_.valid).reduce(_ || _)

  // Two-pass round-robin: check from (lastGrant+1) to n-1, then 0 to lastGrant
  var found = false.B
  var sel   = lastGrant

  // We scan all n candidates in round-robin order using a priority chain
  val candidates = Wire(Vec(n, Bool()))
  for (i <- 0 until n) {
    candidates(i) := io.in(i).valid
  }

  // Compute round-robin priority: grant to smallest index > lastGrant that is valid,
  // falling back to smallest valid index <= lastGrant.
  val grantFound  = Wire(Bool())
  val grantIdx    = Wire(UInt(log2Ceil(n).W))
  grantFound := false.B
  grantIdx   := 0.U

  // Priority encoder after lastGrant (wrap-around)
  // Check each input in order (lastGrant+1, lastGrant+2, ..., lastGrant+n) mod n
  // Use a fold to implement priority
  var foundWire = WireDefault(false.B)
  var idxWire   = WireDefault(0.U(log2Ceil(n).W))

  for (k <- (n - 1) to 0 by -1) {
    // Candidate at offset k from (lastGrant+1)
    val offset = k.U
    val idx    = (lastGrant + 1.U + offset) % n.U
    when(io.in(idx).valid) {
      foundWire := true.B
      idxWire   := idx
    }
  }

  chosen := idxWire

  // Drive outputs
  io.out.valid := anyValid
  io.out.bits  := io.in(chosen).bits
  io.chosen    := chosen

  // Ready: only the chosen input gets ready propagated
  for (i <- 0 until n) {
    io.in(i).ready := io.out.ready && anyValid && (chosen === i.U)
  }

  // Update lastGrant on a successful handshake
  when(io.out.valid && io.out.ready) {
    lastGrant := chosen
  }
}

