/** IndexAllocator: manages a pool of indices.
  *
  * @param capacity Number of indices (0 to capacity-1).
  *
  * Interface:
  *   alloc : Decoupled output - valid=available index exists, bits=next index to allocate.
  *           Consumer drives ready=true to actually allocate.
  *   free  : Flipped(Decoupled) input - valid=return an index, bits=which index to free.
  *           Module drives ready=true when it can accept a freed index.
  *
  * Behavior:
  *   - Initially all indices are available.
  *   - alloc.valid = true when pool is non-empty.
  *   - alloc.bits = lowest available index (in order of allocation: 0, 1, 2, ...).
  *   - free.ready = true when at least one index has been allocated (pool is not full).
  *   - When alloc fires: mark that index as allocated.
  *   - When free fires: return that index to the pool (available next cycle).
  *   - Both can fire on the same cycle.
  *
  * IndexAllocatorShifting: implements allocation using a shift-register free list.
  *   Indices are returned to the front of the queue when freed, maintaining
  *   the order in which they were freed for the "out of order free" test.
  */
abstract class IndexAllocator(val capacity: Int) extends Module {
  val io = IO(new Bundle {
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    val free  = Flipped(Decoupled(UInt(log2Ceil(capacity).W)))
  })
}

/** Shifting free list implementation.
  *
  * The free list is a queue stored in a Vec. Freed indices are pushed to the
  * front (shifting others up). Allocated indices are taken from the front.
  *
  * This ensures the "out of order free" test works: freed indices come back
  * in the order they were freed.
  */
class IndexAllocatorShifting(capacity: Int) extends IndexAllocator(capacity) {

  // Free list: freeList(0) is the next to allocate
  // freeCount: how many are in the free list
  val freeList  = Reg(Vec(capacity, UInt(log2Ceil(capacity).W)))
  val freeCount = RegInit(capacity.U(log2Ceil(capacity + 1).W))

  // Initialize free list to 0, 1, 2, ..., capacity-1
  val initialized = RegInit(false.B)
  when(!initialized) {
    for (i <- 0 until capacity) {
      freeList(i) := i.U
    }
    initialized := true.B
  }

  // nAllocated = capacity - freeCount
  val nAllocated = capacity.U - freeCount

  // alloc: valid when free list is non-empty
  io.alloc.valid := (freeCount > 0.U) && initialized
  io.alloc.bits  := freeList(0)

  // free: ready when at least one index has been allocated
  io.free.ready := (nAllocated > 0.U)

  // Determine actions this cycle
  val doAlloc = io.alloc.valid && io.alloc.ready
  val doFree  = io.free.valid && io.free.ready

  when(doAlloc && !doFree) {
    // Shift free list left by 1
    for (i <- 0 until capacity - 1) {
      freeList(i) := freeList(i + 1)
    }
    freeCount := freeCount - 1.U
  }.elsewhen(!doAlloc && doFree) {
    // Push freed index to front, shift others right by 1
    for (i <- 1 until capacity) {
      freeList(i) := freeList(i - 1)
    }
    freeList(0) := io.free.bits
    freeCount   := freeCount + 1.U
  }.elsewhen(doAlloc && doFree) {
    // Alloc from front and free to front simultaneously
    // Net result: freeCount stays the same, but front is replaced with freed index
    // after shifting
    // Effectively: remove freeList(0) (allocated), then insert free.bits at front
    for (i <- 1 until capacity) {
      freeList(i) := freeList(i - 1)
    }
    freeList(0) := io.free.bits
    // freeCount unchanged
  }
}

