package common

import chisel3._
import chisel3.util._

/** IndexAllocator: manages a pool of indices.
  *
  * @param capacity Number of indices (0 to capacity-1).
  *
  * Interface:
  *   alloc : Decoupled output - valid when pool is non-empty, bits = next allocatable index.
  *   free  : Flipped Decoupled input - consumer returns an index.
  *
  * Invariants:
  *   - alloc.valid  = freeCount > 0 (pool non-empty)
  *   - free.ready   = nAllocated > 0 (at least one index is outstanding)
  *   - Freed indices are returned in FIFO order (order they were freed).
  */
abstract class IndexAllocator(val capacity: Int) extends Module {
  val io = IO(new Bundle {
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    val free  = Flipped(Decoupled(UInt(log2Ceil(capacity).W)))
  })
}

/** IndexAllocatorShifting: shift-register based free list.
  *
  * The free list is stored as a compact array. Freed indices are enqueued at
  * the back; allocated indices are taken from the front (FIFO order of freed).
  *
  * Special case: when the pool was fully empty and an index is freed, it is
  * immediately visible at alloc.bits (bypass / forwarding).
  */
class IndexAllocatorShifting(capacity: Int) extends IndexAllocator(capacity) {

  // freeList(0) is the next to allocate (front of queue)
  // Elements are pushed at freeList(freeCount) and popped from freeList(0)
  val freeList  = RegInit(VecInit((0 until capacity).map(_.U(log2Ceil(capacity).W))))
  val freeCount = RegInit(capacity.U(log2Ceil(capacity + 1).W))
  val nAllocated = capacity.U - freeCount

  // Determine which operations fire this cycle (combinatorial)
  val doAlloc = io.alloc.valid && io.alloc.ready
  val doFree  = io.free.valid && io.free.ready

  // Combinatorial next-state signals
  val nextFreeList  = Wire(Vec(capacity, UInt(log2Ceil(capacity).W)))
  val nextFreeCount = Wire(UInt(log2Ceil(capacity + 1).W))

  // Default: no change
  nextFreeList  := freeList
  nextFreeCount := freeCount

  when(doAlloc && !doFree) {
    // Pop from front: shift left
    for (i <- 0 until capacity - 1) {
      nextFreeList(i) := freeList(i + 1)
    }
    nextFreeCount := freeCount - 1.U
  }.elsewhen(!doAlloc && doFree) {
    // Push to back: append at freeCount position
    for (i <- 0 until capacity) {
      when(i.U === freeCount) {
        nextFreeList(i) := io.free.bits
      }
    }
    nextFreeCount := freeCount + 1.U
  }.elsewhen(doAlloc && doFree) {
    // Pop from front and push to back simultaneously.
    // Shift left by 1 (remove front) and append freed at new back position.
    for (i <- 0 until capacity - 1) {
      nextFreeList(i) := freeList(i + 1)
    }
    // New back position = freeCount - 1 (after removing front)
    for (i <- 0 until capacity) {
      when(i.U === (freeCount - 1.U)) {
        nextFreeList(i) := io.free.bits
      }
    }
    // freeCount unchanged
    nextFreeCount := freeCount
  }

  // Register update
  freeList  := nextFreeList
  freeCount := nextFreeCount

  // Combinatorial output (with bypass for the "Flow" test)
  // alloc.valid: combinatorially valid when freeCount > 0 OR a free is happening now
  // alloc.bits: from freeList(0) normally, but if freeCount=0 and doFree: from free.bits
  val bypassActive = (freeCount === 0.U) && io.free.valid
  io.alloc.valid := (freeCount > 0.U) || bypassActive
  io.alloc.bits  := Mux(bypassActive && freeCount === 0.U, io.free.bits, freeList(0))

  // free.ready: at least one index has been allocated
  io.free.ready := (nAllocated > 0.U)
}

