/** Intermediate state after Stage 1 (multiply).
  *
  * The 48-bit product mantissa represents the integer (sigA * sigB).
  * The actual value of the product is:
  *   prodMantissa * 2^(prodExp - 173)
  * where prodExp = expA + expB - 127 (biased).
  */
class FmaState1 extends Bundle {
  val prodSign     = Bool()
  val prodExp      = SInt(10.W)   // can be negative for underflow
  val prodMantissa = UInt(48.W)
  val isNaN        = Bool()
  val isInf        = Bool()
  // Addend (inc fields)
  val addSign      = Bool()
  val addExp       = UInt(8.W)
  val addMantissa  = UInt(23.W)
