  val resultSign   = Bool()
  val prodExp      = SInt(10.W)
  val prodMantissa = UInt(48.W)
  val addAligned   = UInt(48.W)
  val addSign      = Bool()
  val isNaN        = Bool()
  val isInf        = Bool()
}

object Fma {

  /** Stage 1: Multiply ina * inb, pass inc through. */
  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val s1 = Wire(new FmaState1)

    val a = cmd.ina
    val b = cmd.inb
    val c = cmd.inc

    // Product sign
    s1.prodSign := a.sign ^ b.sign

    // 24-bit significands (with implicit leading 1)
