      val addSigned  = Mux(s2.addSign,    (~addVal)  + 1.U, addVal)(48, 0)

      // Sum with carry-out (50-bit result)
      val sumRaw = Cat(0.U(1.W), prodSigned) + Cat(0.U(1.W), addSigned)  // 50-bit

      // Determine result sign from the MSB of the 49-bit signed sum
      val sumSign = sumRaw(49)
      val sumMag  = Mux(sumSign, (~sumRaw(49, 0)) + 1.U, sumRaw(49, 0))(48, 0)  // 49-bit magnitude

      // Find the position of the leading 1 in sumMag (0 = LSB)
      val leadPos = PriorityEncoder(Reverse(sumMag))  // gives index of highest set bit

      // Normalize: extract 23-bit mantissa
      // The result value = sumMag * 2^(prodExp - 173)
      // = (1 + frac) * 2^leadPos * 2^(prodExp - 173)
      // biasedExp = leadPos + prodExp - 173 + 127
      //           = leadPos + prodExp - 46
      val rawExp = leadPos.asSInt + s2.prodExp - 46.S  // signed to detect overflow/underflow

      // Extract mantissa: bits (leadPos-1) down to (leadPos-23) of sumMag
      // Shift right by (leadPos - 23) to get leadPos at bit 23
      val shiftAmt = Mux(leadPos >= 23.U, leadPos - 23.U, 0.U)(5, 0)
      val shiftedRight = (sumMag >> shiftAmt)(23, 0)  // bit 23 is the leading 1, bits [22:0] are mantissa

      // When leadPos < 23: we need to shift LEFT, but then the number is subnormal
      // For simplicity, we flush subnormals to zero (handle separately).
      // When leadPos >= 23: normal case.
      val mantissaRaw = shiftedRight(22, 0)

      // Round-to-nearest-even
      // Round bit: bit (leadPos - 23 - 1) of sumMag
      val roundBitPos = Mux(leadPos >= 24.U, leadPos - 24.U, 0.U)(5, 0)
      val roundBit    = Mux(leadPos >= 24.U, (sumMag >> roundBitPos)(0), 0.U)
      val stickyMask  = Mux(leadPos >= 24.U,
        ~((~0.U(49.W)) << roundBitPos)(48, 0),
        0.U(49.W))
      val stickyBit   = (sumMag & stickyMask).orR
      val doRound     = roundBit.asBool && (stickyBit || mantissaRaw(0))
      val mantRounded = mantissaRaw + Mux(doRound, 1.U, 0.U)
      val mantOverflow = doRound && mantRounded(23)
      val finalMantissa = Mux(mantOverflow, 0.U(23.W), mantRounded(22, 0))
      val finalExp      = Mux(mantOverflow, rawExp + 1.S, rawExp)

      val isZeroResult = (sumMag === 0.U)

      when(isZeroResult) {
        result.sign     := false.B
        result.exponent := 0.U
        result.mantissa := 0.U
      }.elsewhen(finalExp >= 255.S) {
        // Overflow -> infinity
        result.sign     := sumSign
        result.exponent := 0xFF.U
        result.mantissa := 0.U
      }.elsewhen(finalExp <= 0.S || leadPos < 23.U) {
        // Underflow -> flush to zero
        result.sign     := sumSign
        result.exponent := 0.U
        result.mantissa := 0.U
      }.otherwise {
        result.sign     := sumSign
        result.exponent := finalExp(7, 0).asUInt
        result.mantissa := finalMantissa
      }
    }

    result
