      when(rShift >= 72.U) {
        addAligned := 0.U
      }.otherwise {
        addAligned := (addSig72 >> rShift)(71, 0)
      }
    }

    s2.addAligned := addAligned
    s2.addSign    := s1.addSign
    s2
  }

  /** Stage 3: Add product and addend (sign-magnitude), normalize, produce Fp32.
    *
    * Both operands are 72-bit values at scale 2^(prodExp - 197).
    * Sum = sumMag (72-bit) at same scale.
    * The leading bit of sumMag is at position leadPos.
    * biasedExp = leadPos + prodExp - 197 + 127 = leadPos + prodExp - 70
    */
  def FmaStage3(s2: FmaState2): Fp32 = {
    val result = Wire(new Fp32)

    when(s2.isNaN) {
      result.sign     := false.B
      result.exponent := 0xFF.U
      result.mantissa := (1 << 22).U
    }.elsewhen(s2.isInf) {
      result.sign     := s2.prodSign
      result.exponent := 0xFF.U
      result.mantissa := 0.U
    }.otherwise {
      // Sign-magnitude addition
      val sameSign = (s2.prodSign === s2.addSign)
      val sumMag   = Wire(UInt(73.W))
      val sumSign  = Wire(Bool())

      when(sameSign) {
        sumMag  := (s2.prodAligned +& s2.addAligned)(72, 0)
        sumSign := s2.prodSign
      }.otherwise {
        val prodBigger = (s2.prodAligned >= s2.addAligned)
        when(prodBigger) {
          sumMag  := (s2.prodAligned - s2.addAligned)(72, 0)
          sumSign := s2.prodSign
        }.otherwise {
          sumMag  := (s2.addAligned - s2.prodAligned)(72, 0)
          sumSign := s2.addSign
        }
      }

      // leadPos: index of the highest set bit in sumMag (73 bits)
      val leadPos = PriorityEncoder(Reverse(sumMag))  // 0-based, MSB = 72

      // biasedExp = leadPos + prodExp - 70
      val rawExp = leadPos.asSInt + s2.prodExp - 70.S

      // Extract 23-bit mantissa: shift right so leading 1 is at bit 23
      val shiftAmt = Mux(leadPos >= 23.U, (leadPos - 23.U)(6, 0), 0.U(7.W))
      val shifted  = (sumMag >> shiftAmt)(23, 0)
      val mantRaw  = shifted(22, 0)

      // Round-to-nearest-even
      val rPos     = Mux(leadPos >= 24.U, (leadPos - 24.U)(6, 0), 0.U(7.W))
      val rBit     = Mux(leadPos >= 24.U, (sumMag >> rPos)(0), 0.U)
      val sMask    = Mux(leadPos >= 24.U, (~((~0.U(73.W)) << rPos))(72, 0), 0.U(73.W))
      val sBit     = (sumMag & sMask).orR
      val doRound  = rBit.asBool && (sBit || mantRaw(0))
      val mantRnd  = (mantRaw +& Mux(doRound, 1.U, 0.U))(23, 0)
      val mOvf     = doRound && mantRnd(23)
      val fMant    = Mux(mOvf, 0.U(23.W), mantRnd(22, 0))
      val fExp     = Mux(mOvf, rawExp + 1.S, rawExp)

      val zeroRes = (sumMag === 0.U)

      when(zeroRes) {
        result.sign := false.B; result.exponent := 0.U; result.mantissa := 0.U
      }.elsewhen(fExp >= 255.S) {
        result.sign := sumSign; result.exponent := 0xFF.U; result.mantissa := 0.U
      }.elsewhen(fExp <= 0.S || leadPos < 23.U) {
        result.sign := sumSign; result.exponent := 0.U; result.mantissa := 0.U
      }.otherwise {
        result.sign     := sumSign
        result.exponent := fExp(7, 0).asUInt
        result.mantissa := fMant
      }
    }

    result
  }
}

